@import url('https://fonts.googleapis.com/css2?family=Press+Start+2P&family=VT323&family=IBM+Plex+Mono:wght@400;500;600;700&display=swap');

/* Pixel — 8-bit lo-fi, dithered textures, hard 2px pixel borders, stepped shadows */
.theme-pixel {
  --bg: oklch(0.22 0.05 265);
  --surface: oklch(0.29 0.055 265);
  --surface-2: oklch(0.36 0.06 265);
  --fg: oklch(0.96 0.02 100);
  --fg-muted: oklch(0.75 0.04 250);
  --accent: oklch(0.78 0.2 145);
  --accent-fg: oklch(0.18 0.05 265);
  --accent-2: oklch(0.72 0.19 30);
  --line: oklch(0.14 0.04 265);
  --success: oklch(0.78 0.2 145);
  --warning: oklch(0.85 0.18 90);
  --danger: oklch(0.62 0.23 25);

  --radius: 0rem;
  --radius-sm: 0rem;
  --radius-lg: 0rem;
  --radius-pill: 0rem;

  --shadow-1: 2px 2px 0 0 var(--line);
  --shadow-2: 4px 4px 0 0 var(--line);
  --shadow-3: 6px 6px 0 0 var(--line);
  --glow: 0 0 0 2px var(--accent);

  --border-width: 2px;
  --blur-amount: 0px;

  --font-display: "Press Start 2P", ui-monospace, monospace;
  --font-body: "VT323", "IBM Plex Mono", ui-monospace, monospace;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;

  --tracking-display: 0.02em;
  --label-transform: uppercase;
  --label-tracking: 0.14em;

  background-color: var(--bg);
  /* dithered checker texture */
  background-image:
    linear-gradient(45deg, oklch(1 0 0 / 0.04) 25%, transparent 25%),
    linear-gradient(-45deg, oklch(1 0 0 / 0.04) 25%, transparent 25%);
  background-size: 8px 8px;
  color: var(--fg);
  font-family: var(--font-body);
  font-size: 1.05rem;
  image-rendering: pixelated;
}

.theme-pixel h1,
.theme-pixel h2,
.theme-pixel h3,
.theme-pixel h4 {
  font-family: var(--font-display);
  font-weight: 400;
  line-height: 1.5;
  letter-spacing: var(--tracking-display);
}

.theme-pixel h1 {
  font-size: clamp(1.4rem, 4vw, 2.4rem);
}

.theme-pixel button,
.theme-pixel input,
.theme-pixel textarea,
.theme-pixel select {
  font-family: var(--font-mono);
}

/* signature */
.theme-pixel { image-rendering: pixelated; }
.theme-pixel h1 { text-shadow: 4px 4px 0 var(--accent-2); }
.theme-pixel button { box-shadow: 3px 3px 0 var(--fg); transition: none; }
.theme-pixel button:active { transform: translate(3px, 3px); box-shadow: none; }
.theme-pixel * { border-radius: 0 !important; }

/* depth */
.theme-pixel thead th { background: var(--line); color: var(--fg); font-family: var(--font-display); font-size: 0.65rem; text-transform: uppercase; letter-spacing: 0.1em; border-bottom: 2px solid var(--accent); }
.theme-pixel td { border-bottom: 2px dotted var(--line); }
.theme-pixel tbody tr:hover td { background: var(--surface-2); box-shadow: inset 3px 0 0 var(--accent); }
.theme-pixel input, .theme-pixel textarea, .theme-pixel select { border: 2px solid var(--fg); background: var(--line); color: var(--fg); box-shadow: inset 2px 2px 0 oklch(0.1 0.03 265); transition: none; }
.theme-pixel input:focus-visible, .theme-pixel textarea:focus-visible, .theme-pixel select:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; box-shadow: inset 2px 2px 0 oklch(0.1 0.03 265); }
.theme-pixel kbd { font-family: var(--font-display); font-size: 0.6rem; border: 2px solid var(--fg); background: var(--surface-2); padding: 0.2em 0.45em; box-shadow: 2px 2px 0 var(--line); }
.theme-pixel a { color: var(--accent); text-decoration: none; border-bottom: 2px dashed var(--accent); }
.theme-pixel a:hover { background: var(--accent); color: var(--accent-fg); border-bottom-style: solid; }
.theme-pixel ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-pixel ::-webkit-scrollbar { width: 16px; height: 16px; }
.theme-pixel ::-webkit-scrollbar-track { background: var(--line); background-image: linear-gradient(45deg, oklch(1 0 0 / 0.06) 25%, transparent 25%), linear-gradient(-45deg, oklch(1 0 0 / 0.06) 25%, transparent 25%); background-size: 6px 6px; }
.theme-pixel ::-webkit-scrollbar-thumb { background: var(--fg); border: 3px solid var(--line); border-radius: 0; }
.theme-pixel ::-webkit-scrollbar-corner { background: var(--line); }
.theme-pixel .label-caps { font-family: var(--font-display); font-size: 0.55rem; background: var(--surface-2); border: 2px solid var(--line); padding: 0.25em 0.5em; }
.theme-pixel .themed-border { border: 2px solid var(--fg); box-shadow: 0 0 0 2px var(--line), 4px 4px 0 2px var(--line); }
.theme-pixel hr { border: none; height: 4px; background-image: repeating-linear-gradient(90deg, var(--accent) 0 8px, transparent 8px 16px); }

/* alt mode: DMG hand-held — pea-soup Game Boy screen, four-shade discipline */
.theme-pixel.alt-mode {
  --bg: oklch(0.83 0.08 125);
  --surface: oklch(0.88 0.07 125);
  --surface-2: oklch(0.75 0.09 125);
  --fg: oklch(0.28 0.06 130);
  --fg-muted: oklch(0.42 0.07 128);
  --accent: oklch(0.4 0.09 130);
  --accent-fg: oklch(0.9 0.06 125);
  --accent-2: oklch(0.55 0.09 128);
  --line: oklch(0.35 0.07 130);
  --shadow-1: 2px 2px 0 0 var(--line);
  --shadow-2: 4px 4px 0 0 var(--line);
  --shadow-3: 6px 6px 0 0 var(--line);
  --glow: 0 0 0 2px var(--accent);
  background-image:
    linear-gradient(45deg, oklch(0.3 0.06 130 / 0.05) 25%, transparent 25%),
    linear-gradient(-45deg, oklch(0.3 0.06 130 / 0.05) 25%, transparent 25%);
  background-size: 8px 8px;
}
.theme-pixel.alt-mode h1 { text-shadow: 3px 3px 0 var(--surface-2); }
.theme-pixel.alt-mode input, .theme-pixel.alt-mode textarea, .theme-pixel.alt-mode select { background: var(--surface); box-shadow: inset 2px 2px 0 oklch(0.62 0.08 126); }
.theme-pixel.alt-mode input:focus-visible, .theme-pixel.alt-mode textarea:focus-visible { box-shadow: inset 2px 2px 0 oklch(0.62 0.08 126); }
.theme-pixel.alt-mode thead th { background: var(--surface-2); border-bottom-color: var(--fg); }
.theme-pixel.alt-mode ::-webkit-scrollbar-track { background: var(--surface-2); }
.theme-pixel.alt-mode ::-webkit-scrollbar-thumb { background: var(--fg); border-color: var(--surface-2); }
.theme-pixel.alt-mode a:hover { background: var(--fg); color: var(--surface); }
.theme-pixel.alt-mode ::selection { background: var(--fg); color: var(--surface); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
